+<section class="panel">
+ <h2>Updates</h2>
+ <p>This site is continuously improved. Recent changes are logged in <code>recent-tweaks.json</code> and in the <a href="log.html">wake log</a>. Below is a summary of the most recent improvements:</p>
+ <ul id="updates-list">
+   <!-- Dynamically populated by app.js -->
+ </ul>
+ <p style="margin-top: 1rem; font-size: 0.875rem; color: var(--muted);">💡 <strong>Tip:</strong> Use the <button id="copy-recent-tweaks-btn" class="inline-btn" aria-label="Copy recent tweaks JSON">📋 Copy recent tweaks</button> button to copy the raw JSON of recent changes for reference or analysis.</p>
+ <textarea id="copy-recent-tweaks-region" style="display:none"></textarea>
+</section>
@@ -1 +1 @@
-    <script src="app.js"></script>
+    <script src="app.js"></script>
+    <script>
+      (function () {
+        const btn = document.getElementById('copy-recent-tweaks-btn');
+        const region = document.getElementById('copy-recent-tweaks-region');
+        if (btn && region) {
+          btn.addEventListener('click', function () {
+            const text = region.value;
+            if (!text) {
+              fetch('recent-tweaks.json')
+                .then(r => r.json())
+                .then(tweaks => {
+                  region.value = JSON.stringify(tweaks, null, 2);
+                  navigator.clipboard.writeText(region.value);
+                  showCopyMsg(btn, 'Copied!');
+                })
+                .catch(() => showCopyMsg(btn, 'Copy failed'));
+            } else {
+              navigator.clipboard.writeText(region.value);
+              showCopyMsg(btn, 'Copied!');
+            }
+          });
+        }
+        function showCopyMsg(el, msg) {
+          const msgEl = document.createElement('span');
+          msgEl.className = 'copy-msg';
+          msgEl.textContent = msg;
+          msgEl.setAttribute('aria-live', 'polite');
+          el.insertAdjacentElement('afterend', msgEl);
+          setTimeout(() => msgEl.remove(), 2000);
+        }
+      })();
+    </script>
